-- Run in Supabase SQL Editor
create table if not exists public.site_settings(id integer primary key default 1 check(id=1),content jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
insert into public.site_settings(id,content) values(1,'{}'::jsonb) on conflict(id) do nothing;
create table if not exists public.appointments(id bigint generated by default as identity primary key,name text not null,phone text not null,email text,service text,date date,message text,status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz not null default now());
alter table public.site_settings enable row level security; alter table public.appointments enable row level security;
drop policy if exists "Public can read site settings" on public.site_settings; create policy "Public can read site settings" on public.site_settings for select to anon,authenticated using(true);
drop policy if exists "Authenticated can edit site settings" on public.site_settings; create policy "Authenticated can edit site settings" on public.site_settings for all to authenticated using(auth.uid() is not null) with check(auth.uid() is not null);
drop policy if exists "Visitors can request appointments" on public.appointments; create policy "Visitors can request appointments" on public.appointments for insert to anon,authenticated with check(status='pending');
drop policy if exists "Authenticated can manage appointments" on public.appointments; create policy "Authenticated can manage appointments" on public.appointments for all to authenticated using(auth.uid() is not null) with check(auth.uid() is not null);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('clinic-images','clinic-images',true,5242880,array['image/jpeg','image/png','image/webp','image/gif','image/avif']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Public view clinic images" on storage.objects; create policy "Public view clinic images" on storage.objects for select using(bucket_id='clinic-images');
drop policy if exists "Authenticated upload clinic images" on storage.objects; create policy "Authenticated upload clinic images" on storage.objects for insert to authenticated with check(bucket_id='clinic-images' and auth.uid() is not null);
drop policy if exists "Authenticated update clinic images" on storage.objects; create policy "Authenticated update clinic images" on storage.objects for update to authenticated using(bucket_id='clinic-images' and auth.uid() is not null) with check(bucket_id='clinic-images' and auth.uid() is not null);
drop policy if exists "Authenticated delete clinic images" on storage.objects; create policy "Authenticated delete clinic images" on storage.objects for delete to authenticated using(bucket_id='clinic-images' and auth.uid() is not null);
-- Starter policies allow any authenticated user to edit. Restrict to an explicit admin allowlist before collecting real patient data.
